parameters.jsCode:
// Lee la salida de GPT - Traducir, valida la traduccion y deja preparadas las DOS
// filas de posts_translations: la del idioma original y la del idioma opuesto.
const base = $('Parsear JSON').item.json;
let raw = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
let t = {};
try {
  if (typeof raw === 'string') {
    t = JSON.parse(raw.trim().replace(/^\x60{3}json\s*/i, "").replace(/\x60{3}\s*$/, ""));
  } else if (raw && typeof raw === 'object') {
    t = raw;
  }
} catch (e) {
  t = {};
}

const originalLocale = base.original_locale === 'en' ? 'en' : 'es';
const targetLocale = originalLocale === 'es' ? 'en' : 'es';

const slugify = (value) => String(value || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 80)
  .replace(/-+$/, '');

const recortar = (value, max) => {
  const s = String(value || '').trim();
  if (s.length <= max) return s;
  const corte = s.slice(0, max);
  const esp = corte.lastIndexOf(' ');
  return (esp > max * 0.6 ? corte.slice(0, esp) : corte).trim();
};

const titleT = String(t.title || '').trim();
const contentT = String(t.content_html || '').trim();

if (!titleT || contentT.length < 40 || !/<[a-z]/i.test(contentT)) {
  throw new Error('GPT - Traducir devolvio una traduccion inutilizable (title o content_html vacios o sin HTML). El post NO se inserta y el articulo se reintentara en la siguiente corrida.');
}

let slugT = slugify(t.slug) || slugify(titleT);
if (!slugT || slugT === base.slug) slugT = slugify(base.slug + '-' + targetLocale);

// Control de integridad: mismo multiconjunto de tags en el original y en la traduccion.
const tagsDe = (html) => (String(html).match(/<([a-z][a-z0-9]*)(?=[\s>\/])/gi) || [])
  .map((s) => s.slice(1).toLowerCase())
  .sort()
  .join(',');
const tagsCoinciden = tagsDe(base.content_html) === tagsDe(contentT);

const original = {
  locale: originalLocale,
  title: base.title,
  slug: base.slug,
  content_html: base.content_html,
  meta_title: recortar(base.title, 70),
  meta_description: recortar(base.meta_description, 160)
};

const traducida = {
  locale: targetLocale,
  title: titleT,
  slug: slugT,
  content_html: contentT,
  meta_title: recortar(t.meta_title || titleT, 70),
  meta_description: recortar(t.meta_description || titleT, 160)
};

return [{ json: {
  original_locale: originalLocale,
  target_locale: targetLocale,
  tags_coinciden: tagsCoinciden,
  original: original,
  traducida: traducida
}, pairedItem: { item: 0 } }];

// Resuelve las colisiones contra posts_translations_locale_slug_key UNIQUE (locale, slug)
// y devuelve las DOS filas listas para el upsert.
const prep = $('Preparar traduccion').item.json;
const postId = $('Insertar post').item.json.id;
if (!postId) {
  throw new Error('Insertar post no devolvio id: no se pueden insertar las traducciones.');
}

const existentes = Array.isArray($json.body) ? $json.body : [];
// Sufijo corto y determinista derivado del uuid del post: estable entre reintentos.
const sufijo = '-' + String(postId).replace(/-/g, '').slice(0, 6);

const resolver = (fila) => {
  const choca = existentes.some((r) => r && r.locale === fila.locale && r.slug === fila.slug);
  if (!choca) return { slug: fila.slug, colision: false };
  const raiz = fila.slug.slice(0, 80 - sufijo.length).replace(/-+$/, '');
  return { slug: raiz + sufijo, colision: true };
};

const ahora = new Date().toISOString();
const colisiones = [];

const filas = [prep.original, prep.traducida].map((f) => {
  const r = resolver(f);
  if (r.colision) colisiones.push({ locale: f.locale, slug_pedido: f.slug, slug_final: r.slug });
  return {
    post_id: postId,
    locale: f.locale,
    title: f.title,
    slug: r.slug,
    content_html: f.content_html,
    meta_title: f.meta_title,
    meta_description: f.meta_description,
    updated_at: ahora
  };
});

if (filas.length !== 2 || filas[0].locale === filas[1].locale) {
  throw new Error('Se esperaban dos filas de locales distintos y no es el caso.');
}

return [{ json: {
  filas: filas,
  locales: filas.map((f) => f.locale),
  slugs: filas.map((f) => f.locale + ':' + f.slug),
  colisiones: colisiones,
  tags_coinciden: prep.tags_coinciden
}, pairedItem: { item: 0 } }];

// P2 (guia de cumplimiento) -- checklist editorial mecanico antes de insertar. Si algo falla,
// esta linea lanza un Error: la ejecucion de n8n queda marcada como fallida, SIN insertar el
// post, visible en el historial de ejecuciones para revision humana. No inventa un estado
// 'pendiente_revision' nuevo en la tabla posts -- usa el mecanismo de error que n8n ya tiene.

const datos = $('Parsear JSON').item.json;
const errores = [];

const textoPlano = (datos.content_html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

if (!datos.title || !datos.title.trim()) {
  errores.push('Falta el titulo.');
} else if (datos.title.trim().toLowerCase() === String(datos.source_title || '').trim().toLowerCase()) {
  errores.push('El titulo es una copia literal del titular de la fuente.');
}

if (!textoPlano) {
  errores.push('Falta el contenido.');
} else if (textoPlano.length > 750) {
  errores.push('El contenido supera los 750 caracteres (tiene ' + textoPlano.length + ').');
}

if (!datos.source_url) {
  errores.push('Falta el enlace a la fuente original (source_url).');
}
if (datos.source_id == null) {
  errores.push('Falta el source_id (atribucion estructurada a la fuente).');
}

const senales = [
  /comprar\s+ahora/i, /vender\s+ahora/i, /se[nñ]al\s+de\s+(compra|venta)/i,
  /zona\s+de\s+entrada/i, /take[\s-]?profit/i, /stop[\s-]?loss/i,
  /precio\s+objetivo/i, /target\s+price/i, /\brecomendamos\b/i,
  /\bdebes?\s+(comprar|vender)\b/i, /\b(buy|sell)\s+now\b/i
];
const textoCompleto = (datos.title || '') + ' ' + textoPlano;
for (const patron of senales) {
  if (patron.test(textoCompleto)) {
    errores.push('Lenguaje de senal/recomendacion de inversion detectado.');
    break;
  }
}

if (errores.length > 0) {
  throw new Error('Checklist editorial P2 (auditoria legal) fallo: ' + errores.join(' | '));
}

return $input.all();

// Elige las notas de cada vuelta REPARTIENDO entre fuentes. Antes se tomaban las mas recientes por fecha: una fuente que publica
// muchas (Investing.com, ~10 por hora) se quedaba con todo y las oficiales, que publican poco, casi nunca entraban.
// Ahora va primero la fuente que menos ha publicado en las ultimas 24 h (a igualdad, la que tiene la nota mas reciente), una nota
// por fuente; si sobran plazas, se completan con las mas recientes que queden.
const N = 3;
const fuenteDe = (link) => {
  const l = String(link || '');
  if (/cftc\.gov/i.test(l)) return 'CFTC';
  if (/investing\.com/i.test(l)) return 'Investing.com';
  if (/federalreserve\.gov/i.test(l)) return 'Reserva Federal';
  if (/sec\.gov\/Archives\/edgar\//i.test(l)) return 'EDGAR';
  if (/sec\.gov/i.test(l)) return 'SEC';
  if (/occ\.gov/i.test(l)) return 'OCC';
  if (/fdic\.gov/i.test(l)) return 'FDIC';
  if (/globenewswire\.com/i.test(l)) return 'GlobeNewswire';
  if (/ecb\.europa\.eu/i.test(l)) return 'BCE';
  if (/eia\.gov/i.test(l)) return 'EIA';
  if (/bea\.gov/i.test(l)) return 'BEA';
  return '';
};
const hace24h = Date.now() - 24 * 3600 * 1000;
const pub = $('Publicados recientes').first().json;
const recientes = {};
if (pub && pub.statusCode === 200 && Array.isArray(pub.body)) {
  for (const p of pub.body) {
    if (Date.parse(p.created_at) >= hace24h) {
      const f = fuenteDe(p.source_url);
      if (f) recientes[f] = (recientes[f] || 0) + 1;
    }
  }
}
const items = $input.all().map((it, i) => ({ it, i, t: Date.parse($('Normalizar Item').itemMatching(i).json.pubDate) || 0, f: it.json.fuente || '' }));
items.sort((a, b) => b.t - a.t);
const porFuente = new Map();
for (const x of items) {
  if (!porFuente.has(x.f)) porFuente.set(x.f, []);
  porFuente.get(x.f).push(x);
}
const orden = [...porFuente.keys()].sort((a, b) => (recientes[a] || 0) - (recientes[b] || 0) || porFuente.get(b)[0].t - porFuente.get(a)[0].t);
const elegidos = [];
for (const f of orden) {
  if (elegidos.length >= N) break;
  elegidos.push(porFuente.get(f)[0]);
}
for (const x of items) {
  if (elegidos.length >= N) break;
  if (!elegidos.includes(x)) elegidos.push(x);
}
return elegidos.map(({ it, i }) => ({ json: it.json, pairedItem: { item: i } }));

// F1.1 -- cualquier error de un articulo llega aqui y el lote sigue con el siguiente.
// D2: el rechazo del checklist deja borrador (no se reintenta); un fallo tecnico deja
// borrador con 'error:' y pipeline_claim_post lo reintenta una vez en otra corrida.
const e = $json.error;
let msg = typeof e === 'string' ? e : (e && (e.message || e.description)) || '';
if (!msg) msg = JSON.stringify($json).slice(0, 300);
const esChecklist = msg.includes('Checklist editorial P2');
let feed = {};
try { feed = $('Normalizar Item').item.json || {}; } catch (_) {}
let postId = null;
try { postId = $('Reservar URL').item.json.body[0].id || null; } catch (_) {}
return { json: {
  post_id: typeof postId === 'string' ? postId : null,
  source_url: feed.link || null,
  titulo: feed.title || null,
  fuente: feed.fuente || null,
  pipeline_error: (esChecklist ? 'checklist: ' : 'error: ') + msg.slice(0, 500),
  log_status: esChecklist ? 'draft_checklist' : 'failed',
} };

// F2.3 -- antes habia una peticion a Supabase por articulo (40 seguidas, 8-21 s por corrida);
// ahora 'Publicados recientes' trae de una vez las URLs de los ultimos 10 dias (mas que la ventana de 7 dias de las fuentes oficiales). Falla cerrado: sin esa
// lista no pasa nada (la reserva atomica en Supabase sigue siendo la red de seguridad final).
const r = $('Publicados recientes').first().json;
if (r.statusCode !== 200 || !Array.isArray(r.body)) return [];
const tratados = new Map(r.body.map((p) => [p.source_url, p]));
const reintentable = (p) => p.status === 'draft' && p.origen === 'rss' && (p.pipeline_attempts ?? 0) < 2
  && !String(p.pipeline_error || '').startsWith('checklist:');
const salida = [];
$input.all().forEach((it, i) => {
  const p = tratados.get($('Normalizar Item').itemMatching(i).json.link);
  if (!p || reintentable(p)) salida.push({ json: it.json, pairedItem: { item: i } });
});
return salida;

// F2.4-A -- solo se paga la llamada de GPT de duplicados si el titular comparte alguna entidad
// (nombre propio, sigla o cifra) con un titular reciente: sin ninguna en comun no puede ser la misma
// noticia. Ante la duda (sin entidades, o sin titulares recientes) se pregunta a GPT igual.
const titulares = $('Titulares recientes').item.json;
const candidato = String($('Normalizar Item').item.json.title || '');

const VACIAS = new Set(['the', 'a', 'an', 'of', 'and', 'or', 'for', 'on', 'in', 'to', 'as', 'at', 'by', 'with', 'from',
  'after', 'before', 'over', 'amid', 'is', 'are', 'be', 'its', 'new', 'la', 'el', 'los', 'las', 'lo', 'un', 'una', 'de',
  'del', 'y', 'o', 'en', 'por', 'para', 'con', 'sin', 'tras', 'ante', 'sobre', 'que', 'se', 'su', 'sus', 'al', 'mas', 'nuevo', 'nueva']);

// Los titulares candidatos llegan en ingles o espanol y los publicados en espanol: los activos que
// son nombres comunes (oro, petroleo...) no comparten palabra entre idiomas, asi que se normalizan.
const ACTIVOS = { gold: 'oro', oro: 'oro', silver: 'plata', plata: 'plata', oil: 'petroleo', petroleo: 'petroleo',
  crude: 'petroleo', crudo: 'petroleo', brent: 'petroleo', wti: 'petroleo', copper: 'cobre', cobre: 'cobre',
  gas: 'gas', dollar: 'dolar', dolar: 'dolar', yen: 'yen', euro: 'euro', yuan: 'yuan' };

const entidades = (texto) => {
  const out = new Set();
  const sinTildes = texto.normalize('NFD').replace(/[̀-ͯ]/g, '');
  for (const crudo of sinTildes.split(/[^A-Za-z0-9$%.&]+/)) {
    const w = crudo.replace(/^[.]+|[.]+$/g, '');
    if (!w) continue;
    const baja = w.toLowerCase();
    if (ACTIVOS[baja]) { out.add(ACTIVOS[baja]); continue; }
    if (VACIAS.has(baja)) continue;
    if (/\d/.test(w) || /^[A-Z]{2,}$/.test(w) || /^[A-Z][a-z]/.test(w)) out.add(baja);
  }
  return out;
};

const lista = titulares && titulares.statusCode === 200 && Array.isArray(titulares.body) ? titulares.body : null;
const propias = entidades(candidato);
let comunes = [];
if (lista && propias.size > 0) {
  const recientes = new Set();
  for (const p of lista) for (const e of entidades(String(p.title || ''))) recientes.add(e);
  comunes = [...propias].filter((e) => recientes.has(e));
}
const revisar = !lista || propias.size === 0 || comunes.length > 0;
return { json: { revisar_con_gpt: revisar, entidades_comunes: comunes } };

// Si el sitio compuso la portada (banderas y logos) se usa esa; si no respondio, se publica la imagen sin insignias
const original = $('Optimizar imagen').item.binary?.data;
const compuesta = $input.item.binary?.cover;
return { json: { cover_mode: compuesta ? 'compuesta' : 'respaldo_sin_insignias' }, binary: { data: compuesta ?? original } };

// Mensaje de Discord de un articulo recien publicado: SOLO el titular y el ENLACE A NUESTRO ARTICULO (no a la fuente original).
// SITE_URL y DISCORD_WEBHOOK_URL son variables de entorno de n8n.
// Variable de entorno (n8n del VPS) o variable de n8n (instalacion con licencia); si ninguna existe, el dominio
const leer = (f) => { try { return f(); } catch (e) { return undefined; } };
const SITE = String(leer(() => $env.SITE_URL) || leer(() => $vars.SITE_URL) || 'https://grizzlytraders.com').replace(/\/+$/, '');
const p = $('Parsear JSON').item.json;
const url = SITE + '/articulos/' + p.slug;
const titulo = String(p.title || '').replace(/\s+/g, ' ').trim().slice(0, 300);
// Discord interpreta Markdown: se escapa para que un titular con * _ ~ ` | > # no cambie el formato
const BS = String.fromCharCode(92);
const escMd = (s) => s.split('').map((ch) => ((BS + '*_~`|>#').includes(ch) ? BS + ch : ch)).join('');
return { json: {
  url,
  titulo,
  discord: {
    username: 'Grizzly Traders',
    avatar_url: SITE + '/logo.png',
    content: '**' + escMd(titulo) + '**\n' + url,
    allowed_mentions: { parse: [] }, // un titular nunca debe poder mencionar a @everyone ni a nadie
  },
} };

// Decide qué hacer con la respuesta de Higgsfield: listo, seguir esperando o pasar al respaldo (OpenAI).
// El contador de intentos se guarda por solicitud (no por nodo) para que no se acumule entre las notas de una misma vuelta.
const j = $json;
const id = $('Higgsfield - Enviar').item.json.request_id || 'sin-id';
const sd = $getWorkflowStaticData('global');
sd.hf = sd.hf || {};
if (Object.keys(sd.hf).length > 50) sd.hf = {};
sd.hf[id] = (sd.hf[id] || 0) + 1;
const intentos = sd.hf[id];
const url = j.images && j.images[0] && j.images[0].url;
let decision = 'esperar';
if (j.status === 'completed' && url) decision = 'listo';
else if (['failed', 'nsfw', 'canceled', 'completed'].includes(j.status)) decision = 'fallo';
else if (intentos >= 14) decision = 'fallo'; // ~14 consultas x 12 s: unos 3 minutos
if (decision !== 'esperar') delete sd.hf[id];
return { json: { decision, status: j.status, url: decision === 'listo' ? url : null, intentos } };

// Feed Atom de filings 8-K recientes de EDGAR -> items {title, link, contentSnippet, pubDate, fuente:'EDGAR'}.
// Solo los apartados que son noticia (resultados, adquisiciones, acuerdos, bancarrota, cambios de directivos...); sin enmiendas (8-K/A).
const RELEVANTES = new Set(['1.01', '1.02', '1.03', '2.01', '2.02', '2.05', '2.06', '3.01', '4.02', '5.02', '8.01']);
const dec = (s) => String(s || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const xml = String($json.data || '');
const vistos = new Set();
const salida = [];
for (const e of xml.match(/<entry>[\s\S]*?<\/entry>/g) || []) {
  const titulo = dec((e.match(/<title>([\s\S]*?)<\/title>/) || [])[1]).trim();
  if (/^8-K\/A/i.test(titulo)) continue;
  const link = (e.match(/<link[^>]*href="([^"]+)"/) || [])[1];
  if (!link || vistos.has(link)) continue;
  const resumen = dec((e.match(/<summary[^>]*>([\s\S]*?)<\/summary>/) || [])[1]);
  const apartados = [...resumen.matchAll(/Item\s+(\d\.\d{2})\s*:\s*([^<\n]+)/g)].map((m) => ({ n: m[1], d: m[2].trim() })).filter((a) => RELEVANTES.has(a.n));
  if (!apartados.length) continue;
  const m = titulo.match(/^8-K\s*-\s*(.+?)\s*\(\d+\)\s*\((?:Filer|Subject|Reporting)\)/);
  const empresa = m ? m[1] : titulo.replace(/^8-K\s*-\s*/, '');
  vistos.add(link);
  salida.push({ json: {
    title: empresa + ' - Form 8-K: ' + apartados.map((a) => a.d).join('; '),
    link,
    contentSnippet: 'Filing 8-K de ' + empresa + ' presentado ante la SEC. Apartados: ' + apartados.map((a) => 'Item ' + a.n + ' (' + a.d + ')').join('; ') + '.',
    pubDate: (e.match(/<updated>([^<]+)</) || [])[1] || '',
    fuente: 'EDGAR'
  } });
}
return salida;

// Noticias de Massive -> items. SOLO los comunicados de las propias empresas distribuidos por GlobeNewswire: los medios que Massive
// tambien agrega (The Motley Fool, Zacks...) son contenido editorial de terceros y no se reescriben. Se trabaja solo con el resumen que
// entrega la API; no se raspan las paginas de origen.
const PUBLICADORES_PERMITIDOS = ['GlobeNewswire Inc.'];
const resultados = Array.isArray($json.results) ? $json.results : [];
return resultados
  .filter((a) => PUBLICADORES_PERMITIDOS.includes((a.publisher || {}).name) && a.article_url && String(a.description || '').trim().length >= 200)
  .map((a) => ({ json: {
    title: String(a.title || '').replace(/\s+/g, ' ').trim(),
    link: a.article_url,
    contentSnippet: String(a.description).replace(/\s+/g, ' ').trim(),
    pubDate: a.published_utc,
    fuente: 'GlobeNewswire'
  } }));

// En la pagina indice del filing: el comunicado de prensa (EX-99.1) si existe; si no, el documento principal (8-K).
const html = String($json.data || '');
const docs = [];
for (const fila of html.match(/<tr[^>]*>[\s\S]*?<\/tr>/gi) || []) {
  const celdas = [...fila.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((m) => m[1]);
  if (celdas.length < 4) continue;
  const href = (celdas[2].match(/href="([^"]+)"/) || [])[1];
  const tipo = celdas[3].replace(/<[^>]*>/g, '').trim();
  const limpio = href ? href.replace(/^\/ix\?doc=/, '') : '';
  if (limpio && /\.(htm|html|txt)$/i.test(limpio)) docs.push({ href: limpio, tipo });
}
const elegido = docs.find((d) => /^EX-99\.1$/i.test(d.tipo)) || docs.find((d) => /^8-K$/i.test(d.tipo)) || docs[0];
const url = elegido ? (/^https?:/i.test(elegido.href) ? elegido.href : 'https://www.sec.gov' + elegido.href) : '';
return [{ json: { url, tipo: elegido ? elegido.tipo : '' } }];

// HTML del documento -> texto plano, con la misma forma que devuelve Firecrawl ({ data: { markdown } }) para reutilizar el nodo siguiente.
const ENT = { '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&rsquo;': "'", '&lsquo;': "'", '&ldquo;': '"', '&rdquo;': '"', '&ndash;': '-', '&mdash;': '-', '&#160;': ' ', '&#8217;': "'", '&#8220;': '"', '&#8221;': '"', '&#8212;': '-', '&#8211;': '-' };
let t = String($json.data || '');
t = t.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h\d|table)>/gi, '\n').replace(/<[^>]*>/g, ' ');
t = t.replace(/&#?\w+;/g, (m) => (m in ENT ? ENT[m] : ' '));
const lineas = t.split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter((l) => l.length > 0);
return [{ json: { data: { markdown: lineas.join('\n').slice(0, 20000) } } }];
